export function whyText(lang: 'en' | 'ar', code: string, params: Record<string, unknown> = {}, fallback = ''): string {
  const tpl = WHY[lang][code];
  if (!tpl) return fallback || code;
  return tpl.replace(/\{(\w+)\}/g, (_m, k) => String(params[k] ?? ''));
}
